  "inlineSchema": "datasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\n// -------------------------------------------------------------\n// ENUMS\n// -------------------------------------------------------------\n\nenum Role {\n  ADMIN\n  OPERADOR\n  VENDEDOR\n}\n\nenum OrderStatus {\n  PENDIENTE\n  EN_PREPARACION\n  EN_CAMINO\n  ENTREGADO\n  CANCELADO\n}\n\nenum PaymentStatus {\n  PENDIENTE\n  PAGADO\n  RECHAZADO\n}\n\n// -------------------------------------------------------------\n// 1. USUARIOS Y AUTENTICACIÓN\n// -------------------------------------------------------------\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  name      String\n  role      Role     @default(ADMIN)\n  active    Boolean  @default(true)\n  orders    Order[]\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"users\")\n}\n\n// -------------------------------------------------------------\n// 2. CLIENTES (Canal WhatsApp y Redes)\n// -------------------------------------------------------------\n\nmodel Customer {\n  id        String   @id @default(uuid())\n  name      String\n  phone     String   @unique\n  email     String?\n  address   String?\n  orders    Order[]\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"customers\")\n}\n\n// -------------------------------------------------------------\n// 3. CATÁLOGO DE PRODUCTOS (7 Shots + Jugos VitaJuice)\n// -------------------------------------------------------------\n\nmodel Product {\n  id          String       @id @default(uuid())\n  name        String       @unique\n  description String?\n  category    String       @default(\"SHOT\") // SHOT, JUICE, PACK\n  price       Decimal      @db.Decimal(10, 2)\n  minStock    Int          @default(10)\n  active      Boolean      @default(true)\n  imageUrl    String?\n  recipes     RecipeItem[]\n  orderItems  OrderItem[]\n  createdAt   DateTime     @default(now())\n  updatedAt   DateTime     @updatedAt\n\n  @@map(\"products\")\n}\n\n// -------------------------------------------------------------\n// 4. INVENTARIO DE INSUMOS / MATERIA PRIMA\n// -------------------------------------------------------------\n\nmodel Supply {\n  id            String           @id @default(uuid())\n  name          String           @unique\n  unit          String // \"g\", \"kg\", \"ml\", \"unidad\"\n  currentStock  Decimal          @default(0.00) @db.Decimal(10, 2)\n  minStockAlert Decimal          @default(100.00) @db.Decimal(10, 2)\n  lastCost      Decimal          @default(0.00) @db.Decimal(10, 2) // Costo unitario referencial\n  recipes       RecipeItem[]\n  purchases     SupplyPurchase[]\n  createdAt     DateTime         @default(now())\n  updatedAt     DateTime         @updatedAt\n\n  @@map(\"supplies\")\n}\n\n// -------------------------------------------------------------\n// 5. COMPRAS Y LOTES DE INSUMOS (Trazabilidad y Vencimiento)\n// -------------------------------------------------------------\n\nmodel SupplyPurchase {\n  id             String    @id @default(uuid())\n  supplyId       String\n  supply         Supply    @relation(fields: [supplyId], references: [id], onDelete: Cascade)\n  quantity       Decimal   @db.Decimal(10, 2)\n  unitCost       Decimal   @db.Decimal(10, 2)\n  totalCost      Decimal   @db.Decimal(10, 2)\n  purchaseDate   DateTime  @default(now())\n  expirationDate DateTime? // Fundamental para materias primas perecederas\n  supplier       String? // Proveedor (ej. Mercado Mayorista Frutas)\n  batchNumber    String? // Número de lote\n  createdAt      DateTime  @default(now())\n\n  @@map(\"supply_purchases\")\n}\n\n// -------------------------------------------------------------\n// 6. RECETA / FICHA TÉCNICA (Relación Producto ↔ Insumo)\n// -------------------------------------------------------------\n\nmodel RecipeItem {\n  id             String  @id @default(uuid())\n  productId      String\n  product        Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  supplyId       String\n  supply         Supply  @relation(fields: [supplyId], references: [id], onDelete: Restrict)\n  quantityNeeded Decimal @db.Decimal(10, 3) // Cantidad requerida para 1 unidad de producto\n\n  @@unique([productId, supplyId])\n  @@map(\"recipe_items\")\n}\n\n// -------------------------------------------------------------\n// 7. PEDIDOS Y VENTAS\n// -------------------------------------------------------------\n\nmodel Order {\n  id            String        @id @default(uuid())\n  orderNumber   String        @unique // Ej. VJ-2026-001\n  customerId    String\n  customer      Customer      @relation(fields: [customerId], references: [id])\n  userId        String?\n  user          User?         @relation(fields: [userId], references: [id])\n  status        OrderStatus   @default(PENDIENTE)\n  paymentStatus PaymentStatus @default(PENDIENTE)\n  totalAmount   Decimal       @db.Decimal(10, 2)\n  paymentMethod String? // \"CULQI\", \"YAPE\", \"EFECTIVO\", \"TRANSFERENCIA\"\n  deliveryDate  DateTime?\n  notes         String?\n  items         OrderItem[]\n  payments      Payment[]\n  createdAt     DateTime      @default(now())\n  updatedAt     DateTime      @updatedAt\n\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id        String  @id @default(uuid())\n  orderId   String\n  order     Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product @relation(fields: [productId], references: [id])\n  quantity  Int\n  unitPrice Decimal @db.Decimal(10, 2)\n  subtotal  Decimal @db.Decimal(10, 2)\n\n  @@map(\"order_items\")\n}\n\n// -------------------------------------------------------------\n// 8. PAGOS (Pasarela Culqi y Auditoría)\n// -------------------------------------------------------------\n\nmodel Payment {\n  id            String   @id @default(uuid())\n  orderId       String\n  order         Order    @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  provider      String   @default(\"CULQI\")\n  transactionId String   @unique // Ej. chr_test_66f2c6...\n  amount        Decimal  @db.Decimal(10, 2)\n  currency      String   @default(\"PEN\")\n  status        String // \"SUCCESS\", \"FAILED\"\n  payload       Json? // Respuesta completa de Culqi para auditoría\n  createdAt     DateTime @default(now())\n\n  @@map(\"payments\")\n}\n",
